document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{if(!wood)return;wood.map.dispose();wood.map=makeWood(b.dataset.color==='walnut');document.querySelectorAll('[data-color]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))})});document.querySelector('#motion').onclick=e=>{running=!running;e.target.textContent=running?'Ⅱ':'▶';e.target.setAttribute('aria-pressed',String(running));e.target.setAttribute('aria-label',running?'Pause desk rotation':'Start desk rotation')};let timer;function getBrief(){const a=document.createElement('a');a.href='pilot-brief.txt';a.download='Formdesk-Pilot-Offer.txt';a.click();const notice=document.querySelector('#notice');notice.textContent='Pilot brief downloaded. No enquiry or payment has been submitted.';clearTimeout(timer);timer=setTimeout(()=>notice.textContent='',4500)}document.querySelector('#download-pilot').onclick=getBrief;document.querySelector('#download-pilot-bottom').onclick=getBrief;
